mapper.select:

WHERE u.del_flag = '0'

    AND u.user_name LIKE CONCAT('%', #{userName}, '%')


    AND u.dept_id = #{deptId}


    AND ${params.dataScope}

ORDER BY u.user_id

SELECT user_id, dept_id, user_name, nick_name, data_scope, status, del_flag, create_time, update_time
FROM sys_user
WHERE user_id = #{userId}

SELECT dept_id
FROM sys_user_dept
WHERE user_id = #{userId}
